import{c as o,Z as e,Q as i,j as l,m as r,o as n}from"./chunks/framework.DOi4mjdC.js";const m=JSON.parse('{"title":"枫桥夜泊","description":"","frontmatter":{"title":"枫桥夜泊","author":"张继","dynasty":"唐"},"headers":[],"relativePath":"books/shici/tangshi/9.md","filePath":"books/shici/tangshi/9.md"}'),s={name:"books/shici/tangshi/9.md"};function h(u,a,c,p,d,q){const t=e("PoemNav");return i(),l("div",null,[a[0]||(a[0]=r('<h1 id="枫桥夜泊" tabindex="-1">枫桥夜泊 <a class="header-anchor" href="#枫桥夜泊" aria-label="Permalink to &quot;枫桥夜泊&quot;">​</a></h1><p><strong>[唐] <a href="/authors/zhangji.html">张继</a></strong></p><h2 id="原文" tabindex="-1">原文 <a class="header-anchor" href="#原文" aria-label="Permalink to &quot;原文&quot;">​</a></h2><p>月落乌啼霜满天，江枫渔火对愁眠。 姑苏城外寒山寺，夜半钟声到客船。</p><h2 id="注释" tabindex="-1">注释 <a class="header-anchor" href="#注释" aria-label="Permalink to &quot;注释&quot;">​</a></h2><ul><li>枫桥：在今江苏省苏州市阊门外</li><li>夜泊：夜间把船停靠在岸边</li><li>乌啼：乌鸦啼叫</li><li>霜满天：形容秋夜霜气浓重，仿佛满天都是寒霜</li><li>江枫：江边的枫树</li><li>渔火：渔船上的灯火</li><li>对愁眠：伴着忧愁入睡</li><li>姑苏：苏州的古称</li><li>寒山寺：在苏州城西枫桥镇，因唐代诗僧寒山曾住此而得名</li><li>夜半钟声：唐代寺庙有半夜敲钟的习惯</li></ul><h2 id="译文" tabindex="-1">译文 <a class="header-anchor" href="#译文" aria-label="Permalink to &quot;译文&quot;">​</a></h2><p>月亮西沉，乌鸦啼叫，秋霜满天。江边的枫树和渔船上的灯火，陪伴着满怀愁绪的旅人入眠。姑苏城外的寒山寺，半夜敲响的钟声传到了客船上。</p><h2 id="赏析" tabindex="-1">赏析 <a class="header-anchor" href="#赏析" aria-label="Permalink to &quot;赏析&quot;">​</a></h2><p>这首诗是张继夜泊枫桥时所作，描写了秋夜江边的凄清景象和游子的羁旅之愁，是唐诗中写愁绪的名篇。</p><p>首句&quot;月落乌啼霜满天&quot;，从视觉、听觉、感觉三个角度描绘秋夜的凄清。&quot;月落&quot;写时间已晚，&quot;乌啼&quot;增添凄凉气氛，&quot;霜满天&quot;则渲染了秋夜的寒冷。三个意象叠加，营造出一种萧瑟悲凉的氛围。</p><p>次句&quot;江枫渔火对愁眠&quot;，写诗人对着江枫渔火，满怀愁绪难以入眠。&quot;对&quot;字将诗人与景物相对，&quot;愁眠&quot;点明诗人的心境，羁旅之愁溢于言表。</p><p>后两句&quot;姑苏城外寒山寺，夜半钟声到客船&quot;，是全诗的点睛之笔。诗人以远处传来的夜半钟声，打破了夜的寂静，也打破了诗人的愁思。这钟声在寂静的夜里显得格外清晰，既衬托了夜的幽静，又加深了游子的孤独感。</p><p>全诗意境清幽，情景交融，将秋夜的凄清、游子的愁绪与寺庙的钟声完美融合，成为千古传诵的名篇。寒山寺也因此诗而名扬天下。</p><hr><h2 id="关于作者" tabindex="-1">关于作者 <a class="header-anchor" href="#关于作者" aria-label="Permalink to &quot;关于作者&quot;">​</a></h2><blockquote><p><strong>张继</strong>（约715年－约779年），字懿孙，唐代诗人，襄州（今湖北襄阳）人。其诗多写羁旅之情，风格清秀自然，《枫桥夜泊》是其代表作。</p><p><a href="/authors/zhangji.html">查看作者详情 →</a></p></blockquote>',17)),n(t)])}const b=o(s,[["render",h]]);export{m as __pageData,b as default};
